<?php
namespace App\Http\Controllers;
use App\Services\PeriodGuard; use Illuminate\Http\Request; use Illuminate\Support\Facades\DB;
class SemesterResultController extends Controller {
 public function edit(Request $r,$group,$subject){$p=$r->attributes->get('academic_period');abort_if(!$p,404);$this->scope($r,$group,$subject);$g=DB::table('study_groups')->find($group);$sub=DB::table('subjects')->find($subject);$students=DB::table('students')->where('current_group_id',$group)->where('status','active')->orderBy('last_name')->get();foreach($students as $s){$s->result=DB::table('semester_results')->where(['academic_period_id'=>$p->id,'student_id'=>$s->id,'subject_id'=>$subject])->value('value');}return view('semester.edit',compact('p','g','sub','students'));}
 public function save(Request $r,$group,$subject){$p=$r->attributes->get('academic_period');abort_if(!$p,404);PeriodGuard::writable($p->id);abort_unless($r->user()->canDo('semester.mark'),403);$this->scope($r,$group,$subject);foreach($r->input('result',[]) as $student=>$value){if($value==='')continue;abort_unless(DB::table('students')->where('id',$student)->where('current_group_id',$group)->exists(),422);DB::table('semester_results')->updateOrInsert(['academic_period_id'=>$p->id,'student_id'=>$student,'subject_id'=>$subject,'result_type'=>'semester'],['teacher_id'=>$r->user()->teacher_id,'value'=>$value,'updated_at'=>now(),'created_at'=>now()]);}return back()->with('success','Итоговые оценки сохранены');}
 private function scope(Request $r,$group,$subject){$u=$r->user();if($u->isSuperAdmin()||$u->hasRole('admin')||$u->hasRole('head_academic'))return;abort_unless($u->hasRole('teacher')&&DB::table('schedule_entries')->where('study_group_id',$group)->where('subject_id',$subject)->where('teacher_id',$u->teacher_id)->exists(),403);}
}
